"use client";
/* Inky, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Inky(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("inky"); }, []);
  return React.createElement("piix-sprite", { "name": "inky", ...piixAttrs(props) });
}

export default Inky;
